237:     void allocate_dense_celldata(size_t ncells, size_t nghost, size_t neq, size_t nftl)
238:     {
239:     /*
240:         Both kinds of blocks now share a structure of densely packed core flow data. This routine
241:         allocates the storage for these structures, attempting to keep related bits of data together
242:         on the heap.
243: 
244:         In an older draft of this code, I allocated all of the normal cells in one loop,
245:         then added the ghost cells onto the end later. This caused all of the pointers
246:         in the FVCell classes to no longer be pointing to the right objects, which was
247:         very bad. The solution to this was to use .reserve on the arrays before
248:         filling them, which prevented the pointers from being copied. Now however,
249:         we do the cells and the ghost cells all at once, but we still do .reserve
250:         because it should be faster.
251: 
252:         @author: Nick Gibbons
253:     */
254:         auto gmodel = myConfig.gmodel;
255:         size_t nturb = myConfig.turb_model.nturb;
256:         size_t ngtl = myConfig.n_grid_time_levels;
257: 
258:         celldata.all_cell_idxs.length = ncells;
259:         celldata.halo_cell_ids.length = (ncells + nghost);
260:         celldata.halo_face_ids.length = (ncells + nghost);
261:         foreach(i; 0 .. ncells) celldata.all_cell_idxs[i] = i;
262: 
263:         celldata.nfaces.length = ncells;
264:         celldata.dt_local.length = ncells;
265:         celldata.wall_distances.length = ncells;
266:         celldata.data_is_bad.length = ncells;
267:         celldata.in_turbulent_zone.length = ncells;
268:         celldata.lengths.length = ncells + nghost;
269: 
270:         celldata.areas.length     = ngtl*(ncells + nghost);
271:         celldata.volumes.length   = ngtl*(ncells + nghost);
272:         celldata.positions.length = ngtl*(ncells + nghost);
273: 
274:         // 显式每个时间层已有独立数组；只压缩尾部容量，不改变层数/索引/数值更新。
275:         // 非显式路径保留原分配，待独立运行包和边界索引检查后使用。
276:         size_t stage_storage = (ncells + nghost)*neq;
277:         if (myConfig.solverMode != SolverMode.transient) stage_storage *= nftl;
278:         celldata.U0.length = stage_storage;
279:         if (nftl>1) celldata.U1.length = stage_storage;
280:         if (nftl>2) celldata.U2.length = stage_storage;
281:         if (nftl>3) celldata.U3.length = stage_storage;
282:         if (nftl>4) celldata.U4.length = stage_storage;
283:         celldata.dUdt0.length = stage_storage;
284:         if (nftl>1) celldata.dUdt1.length = stage_storage;
285:         if (nftl>2) celldata.dUdt2.length = stage_storage;
286:         if (nftl>3) celldata.dUdt3.length = stage_storage;
287:         if (nftl>4) celldata.dUdt4.length = stage_storage;
288:         // 记录实际分配容量；仅观察，不参与任何数值更新。
289:         if (myConfig.solverMode == SolverMode.transient) {
290:             writeln("RAH-STORAGE cells=", ncells, " ghosts=", nghost, " neq=", neq,
291:                     " nftl=", nftl, " scalarBytes=", number.sizeof,
292:                     " stageLength=", stage_storage, " payloadBytes=",
293:                     (celldata.U0.length + celldata.U1.length + celldata.U2.length + celldata.U3.length + celldata.U4.length
294:                      + celldata.dUdt0.length + celldata.dUdt1.length + celldata.dUdt2.length + celldata.dUdt3.length + celldata.dUdt4.length)*number.sizeof);
295:         }
296:         celldata.source_terms.length = (ncells + nghost)*neq;
297: 
298:         celldata.flowstates.reserve(ncells + nghost);
299:         celldata.gradients.reserve(ncells + nghost);
300:         celldata.workspaces.reserve(ncells + nghost);
301:         foreach (n; 0 .. ncells+nghost) celldata.flowstates ~= FlowState(gmodel, nturb);
302:         foreach (n; 0 .. ncells+nghost) celldata.gradients ~= FlowGradients(myConfig);
303:         foreach (n; 0 .. ncells+nghost) celldata.workspaces ~= WLSQGradWorkspace();
304: 
305:         version(newton_krylov) {
306:             // 保留NK编译物理分派；显式流动不分配其矩阵/备份工作区。
307:             if (myConfig.solverMode != SolverMode.transient) {
308:                 celldata.cell_jacobians.length = (ncells+nghost)*neq*neq;
309:                 celldata.saved_gradients.reserve(ncells + nghost);
310:                 foreach (n; 0 .. ncells+nghost) celldata.saved_gradients ~= FlowGradients(myConfig);
311:                 celldata.saved_source_terms.length = (ncells + nghost)*neq;
312:                 celldata.doNotPerturb.length = (ncells+nghost);
313:             }
314:         }
315:     }
