317:     void allocate_dense_facedata(size_t nfaces, size_t nbfaces, size_t neq, size_t nftl)
318:     {
319:     /*
320:         Both kinds of blocks now share a structure of densely packed core flow
321:         data. This routine allocates the storage for these structures,
322:         attempting to keep related bits of data together on the heap.
323: 
324:         @author: Nick Gibbons
325:     */
326:         auto gmodel = myConfig.gmodel;
327:         size_t nturb = myConfig.turb_model.nturb;
328:         size_t ngtl = myConfig.n_grid_time_levels;
329: 
330:         facedata.all_face_idxs.length = nfaces;
331:         foreach(i; 0 .. nfaces) facedata.all_face_idxs[i] = i;
332: 
333:         facedata.positions.length = nfaces;
334:         facedata.areas.length = nfaces*ngtl;
335:         facedata.grid_velocities.length = nfaces*ngtl;
336:         facedata.normals.length = nfaces;
337:         facedata.tangents1.length = nfaces;
338:         facedata.tangents2.length = nfaces;
339:         facedata.left_interior_only.length = nfaces;
340:         facedata.right_interior_only.length = nfaces;
341:         facedata.stencil_idxs.length = nfaces;
342:         facedata.fluxes.length = nfaces*neq;
343:         facedata.f2c.length = nfaces;
344: 
345:         if (myConfig.interpolation_order>=2) facedata.l2r2_interp_data.length = nfaces;
346:         if (myConfig.interpolation_order==3) facedata.l3r3_interp_data.length = nfaces;
347: 
348:         facedata.flowstates.reserve(nfaces);
349:         foreach (n; 0 .. nfaces) facedata.flowstates ~= FlowState(gmodel, nturb);
350:         facedata.gradients.reserve(nfaces);
351:         foreach (n; 0 .. nfaces) facedata.gradients ~= FlowGradients(myConfig);
352:         facedata.workspaces.reserve(nfaces);
353:         foreach (n; 0 .. nfaces) facedata.workspaces ~= WLSQGradWorkspace();
354:     }
