341:     @nogc
342:     void identify_reaction_zones(int gtl)
343:     // Adjust the reactions-allowed flag for cells in this block.
344:     {
345:         size_t total_cells_in_reaction_zones = 0;
346:         size_t total_cells = 0;
347:         foreach(cell; cells) {
348:             if ( myConfig.reaction_zones.length > 0 ) {
349:                 cell.fr_reactions_allowed = false;
350:                 foreach(rz; myConfig.reaction_zones) {
351:                     if ( rz.is_inside(cell.pos[gtl], myConfig.dimensions) ) {
352:                         cell.fr_reactions_allowed = true;
353:                     }
354:                 } // foreach rz
355:             } else {

283:     override void init_grid_and_flow_arrays(string gridFileName)
284:     {
285:         grid = new UnstructuredGrid(gridFileName, myConfig.grid_format, myConfig.true_centroids);
286:         if (grid.nvertices != nvertices) {
287:             string msg = format("UnstructuredGrid: incoming grid has %d vertices " ~
288:                                 "but expected %d vertices.", grid.nvertices, nvertices);
289:             throw new FlowSolverException(msg);
290:         }
291:         if (grid.nfaces != nfaces) {
292:             string msg = format("UnstructuredGrid: incoming grid has %d faces " ~
293:                                 "but expected %d faces.", grid.nfaces, nfaces);
294:             throw new FlowSolverException(msg);
295:         }
296:         if (grid.ncells != ncells) {
297:             string msg = format("UnstructuredGrid: incoming grid has %d cells " ~
298:                                 "but expected %d cells.", grid.ncells, ncells);
299:             throw new FlowSolverException(msg);
300:         }
301:         grid.sort_cells_into_bins();
302:         ninteriorfaces = grid.ninteriorfaces;
303: 
304:         // Assemble array storage for finite-volume cells, etc.
305:         bool lsq_workspace_at_vertices = (myConfig.viscous) && (myConfig.spatial_deriv_calc == SpatialDerivCalc.least_squares)
306:             && (myConfig.spatial_deriv_locn == SpatialDerivLocn.vertices);
307:         foreach (i, v; grid.vertices) {
308:             auto new_vtx = new FVVertex(myConfig, lsq_workspace_at_vertices, to!int(i));
309:             new_vtx.pos[0] = v;
310:             vertices ~= new_vtx;
311:         }
312: 
313:         // Allocate densified face and cell data
314:         auto gmodel = myConfig.gmodel;
315:         size_t neq    = myConfig.cqi.n;
316:         size_t nsp    = myConfig.n_species;
317:         size_t nmodes = myConfig.n_modes;
318:         size_t nturb  = myConfig.turb_model.nturb;
319:         size_t nftl   = myConfig.n_flow_time_levels;
320: 
321:         size_t nghost = 0;
322:         foreach (bndry; grid.boundaries) nghost += bndry.face_id_list.length;
323: 
324:         allocate_dense_celldata(ncells, nghost, neq, nftl);
325:         allocate_dense_facedata(nfaces, nghost, neq, nftl); // nghost==nbfaces for unstructured
326: 
327:         // We have some unstructured specific stuff that also needs to be allocated
328:         celldata.face_distances.length = ncells;
329:         celldata.lsqws.length = ncells + nghost;
330:         celldata.cell_cloud_indices.length = ncells;
331:         celldata.c2v.length = ncells;
332:         celldata.lsqgradients.reserve(ncells + nghost);
333:         foreach (i; 0 .. ncells + nghost) celldata.lsqgradients ~= LSQInterpGradients(nsp, nmodes, nturb); // TODO: skip if not needed
334:         // TODO: for now this is only needed for the adjoint solver and/or the check-jacobian tool - we can think about dropping this for the flow solver. KAD 2024-08-28
335:         // 显式路径不使用Jacobian/伴随备份梯度，其他模式保留原分配。
336:         if (myConfig.solverMode != SolverMode.transient) {
337:             celldata.saved_lsqgradients.reserve(ncells + nghost);
338:             foreach (n; 0 .. ncells+nghost) celldata.saved_lsqgradients ~= LSQInterpGradients(myConfig.n_species, myConfig.n_modes, myConfig.turb_model.nturb);
339:         }
340: 
341:         // 观察完整工作区分配，正常梯度和工作区保留。
342:         if (myConfig.solverMode == SolverMode.transient) {
343:             writeln("RAH-WORKSPACE jacobian=", celldata.cell_jacobians.length,
344:                 " sourceBackup=", celldata.saved_source_terms.length,
345:                 " viscousBackup=", celldata.saved_gradients.length,
346:                 " interpBackup=", celldata.saved_lsqgradients.length,
347:                 " perturbBackup=", celldata.doNotPerturb.length,
348:                 " viscous=", celldata.gradients.length, " interp=", celldata.lsqgradients.length,
349:                 " interpWorkspace=", celldata.lsqws.length);
350:         }
351:         facedata.dL.length = nfaces;
352:         facedata.dR.length = nfaces;
353: 
354:         foreach (i, f; grid.faces) {
355:             auto new_face = new FVInterface(myConfig, IndexDirection.none, &facedata, to!int(i));
356:             faces ~= new_face;
357:         }
358: 
359:         cells.reserve(ncells + nghost);
360:         foreach (i, c; grid.cells) {
361:             // Note that the cell id and the index in the cells array are the same.
362:             // We will reply upon this connection in other parts of the flow code.
363:             auto new_cell = new FluidFVCell(myConfig, &celldata, to!int(i));
364:             new_cell.contains_flow_data = true;
365:             new_cell.is_interior_to_domain = true;
366:             cells ~= new_cell;
367:         }
368:         // 观察已构造的内部单元，不触发隐式计算、不修改任何状态。
369:         if (myConfig.solverMode == SolverMode.transient) {
370:             size_t implicitObjects = 0;
371:             foreach (cell; cells) {
372:                 if (cell.dRdU.length || cell.Q_save.length || cell.grad_save !is null ||
373:                     cell.gradients_save !is null || cell.invBlockDiag !is null) implicitObjects++;
374:             }
375:             writeln("RAH-WORKSPACE-CELLS internal=", cells.length, " implicitObjects=", implicitObjects);
376:         }
377:         // Bind the interfaces, vertices and cells together,
378:         // using the indices stored in the unstructured grid.
379:         foreach (i, f; faces) {
380:             foreach (j; grid.faces[i].vtx_id_list) {
381:                 f.vtx ~= vertices[j];
382:             }
383:         }
384:         celldata.outsigns.length=cells.length;
385:         celldata.c2f.length = cells.length;
386:         foreach (i, c; cells) {
387:             foreach (j; grid.cells[i].vtx_id_list) {
388:                 c.vtx ~= vertices[j];
389:                 celldata.c2v[i] ~= j;
390:             }
391:             auto nf = grid.cells[i].face_id_list.length;
392:             if (nf != grid.cells[i].outsign_list.length) {
393:                 string msg = format("Mismatch in face_id_list, outsign_list lengths: %d %d",
394:                                     grid.cells[i].face_id_list.length,
395:                                     grid.cells[i].outsign_list.length);
396:                 throw new FlowSolverException(msg);
397:             }
398:             foreach (j; 0 .. nf) {
399:                 auto my_face = faces[grid.cells[i].face_id_list[j]];
400:                 int my_outsign = grid.cells[i].outsign_list[j];
401:                 c.iface ~= my_face;
402:                 celldata.c2f[i] ~= grid.cells[i].face_id_list[j];
403:                 c.outsign ~= my_outsign;
404:                 celldata.outsigns[i] ~= my_outsign;
405:                 if (my_outsign == 1) {
406:                     if (my_face.left_cell) {
407:                         string msg = format("Already have cell %d attached to left-of-face %d. Attempt to add cell %d.",
408:                                             my_face.left_cell.id, my_face.id, c.id);
409:                         throw new FlowSolverException(msg);
410:                     } else {
411:                         my_face.left_cell = c;
412:                         facedata.f2c[grid.cells[i].face_id_list[j]].left = i;
413:                     }
414:                 } else {
415:                     if (my_face.right_cell) {
416:                         string msg = format("Already have cell %d attached to right-of-face %d. Attempt to add cell %d.",
417:                                             my_face.right_cell.id, my_face.id, c.id);
418:                         throw new FlowSolverException(msg);
419:                     } else {
420:                         my_face.right_cell = c;
421:                         facedata.f2c[grid.cells[i].face_id_list[j]].right = i;
422:                     }
423:                 }
424:             }
425:             celldata.nfaces[i] = celldata.c2f[i].length;
426:             celldata.face_distances[i].length = celldata.nfaces[i];
427:         } // end foreach cells
428:         //
429:         // Set up the lists of indices for look-up of cells and faces
430:         // from a given vertex.
431:         cellIndexListPerVertex.length = vertices.length;
432:         foreach (i, c; cells) {
433:             foreach (vtx; c.vtx) { cellIndexListPerVertex[vtx.id] ~= i; }
434:         }
435:         faceIndexListPerVertex.length = vertices.length;
436:         foreach (i, f; faces) {
437:             foreach (vtx; f.vtx) { faceIndexListPerVertex[vtx.id] ~= i; }
438:         }
439:         //
440:         // Work through the faces on the boundaries and add ghost cells.
441:         if (nboundaries != grid.nboundaries) {
442:             string msg = format("Mismatch in number of boundaries: %d %d",
443:                                 nboundaries, grid.nboundaries);
444:             throw new FlowSolverException(msg);
445:         }
446:         int ghost_cell_id = to!int(cells.length);
447:         foreach (i, bndry; grid.boundaries) {
448:             auto nf = bndry.face_id_list.length;
449:             if (nf != bndry.outsign_list.length) {
450:                 string msg = format("Mismatch in face_id_list, outsign_list lengths: %d %d",
451:                                     bndry.face_id_list.length, bndry.outsign_list.length);
452:                 throw new FlowSolverException(msg);
453:             }
454:             foreach (j; 0 .. nf) {
455:                 FVInterface my_face = faces[bndry.face_id_list[j]];
456:                 my_face.is_on_boundary = true;
457:                 my_face.bc_id = i; // note which boundary this face is on
458:                 int my_outsign = bndry.outsign_list[j];
459:                 bc[i].faces ~= my_face;
460:                 bc[i].outsigns ~= my_outsign;
461:                 my_face.i_bndry = bc[i].outsigns.length - 1;
462:                 if (bc[i].ghost_cell_data_available) {
463:                     // We need ghost_cell_id to match the relevant position in the celldata arrays
464:                     FluidFVCell ghost0 = new FluidFVCell(myConfig, &celldata, ghost_cell_id);
465:                     ghost_cell_id++;
466:                     ghost0.contains_flow_data = bc[i].ghost_cell_data_available;
467:                     ghost0.is_ghost = true;
468:                     bc[i].ghostcells ~= ghost0;
469:                     if (my_outsign == 1) {
470:                         if (my_face.right_cell) {
