565:                             if (f.right_cell && cell_ids.canFind(f.right_cell.id) == false && f.right_cell.contains_flow_data) {
566:                                 c.cell_cloud ~= f.right_cell;
567:                                 cell_ids ~= f.right_cell.id;
568:                                 celldata.cell_cloud_indices[c.id] ~= f.right_cell.id;
569:                             }
570:                         } else {
571:                             if (f.left_cell && cell_ids.canFind(f.left_cell.id) == false && f.left_cell.contains_flow_data) {
572:                                 c.cell_cloud ~= f.left_cell;
573:                                 cell_ids ~= f.left_cell.id;
574:                                 celldata.cell_cloud_indices[c.id] ~= f.left_cell.id;
575:                             }
576:                         }
577:                     } // end foreach face
578:                 } else {
579:                     // apply nearest-node neighbour
580:                     foreach(vtx; c.vtx) {
581:                         foreach(cid; cellIndexListPerVertex[vtx.id])
582:                             if (cell_ids.canFind(cid) == false && cells[cid].contains_flow_data)
583:                                 { c.cell_cloud ~= cells[cid]; cell_ids ~= cid; celldata.cell_cloud_indices[c.id] ~= cid; }
584: 
585:                     }
586:                 }
587:             } // end foreach cell
588:         } else {
589:             foreach (c; cells) {
590:                 // First cell in the cloud is the cell itself.  Differences are taken about it.
591:                 c.cell_cloud ~= c;
592:                 // Subsequent cells are the surrounding cells.
593:                 foreach (i, f; c.iface) {
594:                     if (c.outsign[i] == 1) {
595:                         if (f.right_cell && f.right_cell.contains_flow_data) {
596:                             c.cell_cloud ~= f.right_cell;
597:                             celldata.cell_cloud_indices[c.id] ~= f.right_cell.id;
598:                         }
599:                     } else {
600:                         if (f.left_cell && f.left_cell.contains_flow_data) {
601:                             c.cell_cloud ~= f.left_cell;
602:                             celldata.cell_cloud_indices[c.id] ~= f.left_cell.id;
603:                         }
604:                     }
605:                 } // end foreach face
606:             } // end foreach cell
607:         } // end else
608:         //
609:         // We will now store the cloud of points in cloud_pos for viscous derivative calcualtions.
610:         // This is equivalent to store_references_for_derivative_calc(size_t gtl) in sblock.d
611:         if (myConfig.viscous) {
612:             if (myConfig.spatial_deriv_calc ==  SpatialDerivCalc.divergence) {
613:                 throw new Error("Divergence theorem not implemented for unstructured grid");
614:             }
615:             // else continue on to fill least-squares/finite-difference cloud
616:             final switch (myConfig.spatial_deriv_locn) {
617:             case SpatialDerivLocn.vertices:
618:                 throw new Error("spatial_deriv_locn at vertices not implemented for unstructured grid");
619:                 // no need for break;
620:             case SpatialDerivLocn.faces:
621:                 throw new Error("spatial_deriv_locn at interfaces not implemented for unstructured grid");
622:                 // no need for break;
623:             case SpatialDerivLocn.cells:
624:                 // We will now store the cloud of points in cloud_pos for viscous derivative calcualtions.
625:                 foreach (c; cells) {
626:                     // First cell in the cloud is the cell itself.  Differences are taken about it.
627:                     c.cloud_pos ~= &(c.pos[0]);
628:                     c.cloud_fs ~= c.fs;
629:                     // Subsequent cells are the surrounding cells.
630:                     foreach (i, f; c.iface) {
631:                         c.cloud_pos ~= &(f.pos);
632:                         c.cloud_fs ~= f.fs;
633:                     } // end foreach face
634:                 }
635:             } // end switch (myConfig.spatial_deriv_locn)
636:         } // if myConfig.viscous
637:     } // end init_grid_and_flow_arrays()
638: 
639:     void build_cloud_of_cell_references_at_each_vertex()
640:     {
641:         // For the MLP limiter, we need access to the gradients stored in the cells.
642:         foreach (vtx; vertices) {
643:             foreach(cid; cellIndexListPerVertex[vtx.id]) { vtx.cell_cloud ~= cells[cid]; }
644:         }
